using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tool implementations -----------------------------------------------

var notepad = new Notepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Searches the web for a query and returns a list of result snippets with titles and URLs."),

    AIFunctionFactory.Create(
        ([Description("A concise heading for the note")] string title,
         [Description("The note body text")] string content) =>
        {
            notepad.Add(title, content);
            return $"Note saved: {title}";
        },
        "save_note",
        "Saves a research note for later reference when writing the final summary."),

    AIFunctionFactory.Create(
        () => notepad.GetAll(),
        "get_notes",
        "Retrieves all notes saved so far."),
};

// --- Agent setup --------------------------------------------------------

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI research assistant that searches the web and takes notes to produce a summary.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    });

// --- Main loop ----------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (MAF)           ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine("Enter a research topic (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    notepad.Clear();

    var prompt = $"""
        Research the following topic thoroughly:
        "{topic}"

        Follow these steps:
        1. Search the web for relevant information (use 2-3 different search queries to get broad coverage).
        2. Save important findings as notes using the save_note tool.
        3. After gathering enough information, retrieve your notes with get_notes.
        4. Write a well-structured summary with key findings, citing sources where possible.

        Begin your research now.
        """;

    Console.WriteLine("\nResearching…\n");

    try
    {
        await using var session = await agent.CreateSessionAsync();
        var response = await agent.RunAsync(
            prompt,
            session,
            new ChatClientAgentRunOptions
            {
                ChatOptions = new ChatOptions { MaxOutputTokens = 4096 },
            });

        Console.WriteLine("── Summary ──────────────────────────────────");
        Console.WriteLine(response.Messages.LastOrDefault()?.Text ?? "(no response)");
        Console.WriteLine("─────────────────────────────────────────────\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}\n");
    }
}

Console.WriteLine("Goodbye!");

// === Helper types ========================================================

/// <summary>Simple in-memory note store used by the agent's save_note / get_notes tools.</summary>
sealed class Notepad
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void Add(string title, string content) => _notes.Add((title, content));

    public string GetAll() =>
        _notes.Count == 0
            ? "(no notes yet)"
            : string.Join("\n\n", _notes.Select((n, i) => $"[{i + 1}] {n.Title}\n{n.Content}"));

    public void Clear() => _notes.Clear();
}

/// <summary>
/// Performs web searches using the Google Custom Search JSON API (free tier)
/// or falls back to a simulated search when credentials are not configured.
/// </summary>
static class WebSearchTool
{
    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        var googleApiKey = Environment.GetEnvironmentVariable("GOOGLE_API_KEY");
        var googleCx = Environment.GetEnvironmentVariable("GOOGLE_CX");

        if (!string.IsNullOrEmpty(googleApiKey) && !string.IsNullOrEmpty(googleCx))
        {
            return await LiveSearchAsync(query, googleApiKey, googleCx);
        }

        // Simulated results so the app works out of the box for demonstration.
        return SimulateSearch(query);
    }

    private static async Task<string> LiveSearchAsync(string query, string apiKey, string cx)
    {
        using var http = new HttpClient();
        var url = $"https://www.googleapis.com/customsearch/v1?q={WebUtility.UrlEncode(query)}&key={apiKey}&cx={cx}&num=5";
        var json = await http.GetStringAsync(url);

        using var doc = System.Text.Json.JsonDocument.Parse(json);
        if (!doc.RootElement.TryGetProperty("items", out var items))
        {
            return "No results found.";
        }

        var results = new List<string>();
        foreach (var item in items.EnumerateArray().Take(5))
        {
            var title = item.GetProperty("title").GetString();
            var snippet = item.GetProperty("snippet").GetString();
            var link = item.GetProperty("link").GetString();
            results.Add($"• {title}\n  {snippet}\n  {link}");
        }

        return string.Join("\n\n", results);
    }

    private static string SimulateSearch(string query)
    {
        return $"""
            [Simulated results for "{query}"]

            • Wikipedia — {query}
              Provides a comprehensive overview of {query} covering history, key concepts, and recent developments.
              https://en.wikipedia.org/wiki/{WebUtility.UrlEncode(query)}

            • Latest research on {query} — ScienceDaily
              Researchers have made significant advances in understanding {query}, with new findings published in 2025.
              https://www.sciencedaily.com/search/?keyword={WebUtility.UrlEncode(query)}

            • {query}: A comprehensive guide — Medium
              An in-depth guide covering the fundamentals, applications, and future outlook of {query}.
              https://medium.com/search?q={WebUtility.UrlEncode(query)}

            (Set GOOGLE_API_KEY and GOOGLE_CX environment variables for live web search results.)
            """;
    }
}

