 using System.ComponentModel;
 using System.Net;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 // --- Tool implementations -----------------------------------------------

 var notepad = new Notepad();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(
         ([Description("The search query")] string query) =>
         {
             return WebSearchTool.SearchAsync(query);
         },
         "web_search",
         "Searches the web for a query and returns a list of result snippets with titles and URLs."),

     AIFunctionFactory.Create(
         ([Description("A concise heading for the note")] string title,
          [Description("The note body text")] string content) =>
         {
             notepad.Add(title, content);
             return $"Note saved: {title}";
         },
         "save_note",
         "Saves a research note for later reference when writing the final summary."),

     AIFunctionFactory.Create(
         () => notepad.GetAll(),
         "get_notes",
         "Retrieves all notes saved so far."),
 };

 // --- Agent setup --------------------------------------------------------

 IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 var agent = new ChatClientAgent(
     chatClient,
     new ChatClientAgentOptions
     {
         Name = "ResearchAgent",
         Description = "An AI research assistant that searches the web and takes notes to produce a summary.",
         ChatOptions = new ChatOptions
         {
             Temperature = 0f,
             MaxOutputTokens = 2048,
             Tools = [.. tools],
         },
     });

 // --- Main loop ----------------------------------------------------------

 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║        AI Research Agent (MAF)           ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine("Enter a research topic (or 'quit' to exit):\n");

 while (true)
 {
     Console.Write("> ");
     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
     {
         break;
     }

     notepad.Clear();

     var prompt = $"""
         Research the following topic thoroughly:
         "{topic}"

         Follow these steps:
         1. Search the web for relevant information (use 2-3 different search queries to get broad coverage).
         2. Save important findings as notes using the save_note tool.
         3. After gathering enough information, retrieve your notes with get_notes.
         4. Write a well-structured summary with key findings, citing sources where possible.

         Begin your research now.
         """;

     Console.WriteLine("\nResearching…\n");

     try
     {
         var session = await agent.CreateSessionAsync();
         var response = await agent.RunAsync(
